    TestBed.resetTestingModule();
    const second = makeStore();
    const reloaded = second.items().find((i) => i.id === ID_DUNE);
    expect(reloaded?.seen).toBe(true);
    expect(Object.keys(reloaded ?? {})).not.toContain('watched');
  });
});
