    private _items = signal<WatchItem[]>(this.readItems());

    items = this._items.asReadonly();
    count = computed(() => this._items().length);
    watchedCount = computed(() => this._items().filter(m => m.seen).length)

    constructor() {
        // Normalize any legacy persisted state (e.g. items still stored
        // under the old `watched` key) so later writes use `seen` only.
        this.persist();
    }

    add(movie: TmdbMovie) {
        this._items.update(items =>
            items.some(m => m.id === movie.id) ? items : [...items, { id: movie.id, title: movie.title, poster_path: movie.poster_path, release_date: movie.release_date, seen: false }]
        );
        this.persist();
    }

    remove(id: number) {
        this._items.update(items => items.filter(m => m.id !== id));
        this.persist();
    }

    toggleWatched(id: number) {
        this._items.update(items =>
            items.map(m => m.id === id ? { ...m, seen: !m.seen } : m)
        );
        this.persist();
    }

    private persist() {
        localStorage.setItem(this.KEY, JSON.stringify(this._items()));
    }

    private readItems(): WatchItem[] {
        let stored: unknown;
        try {
            stored = JSON.parse(localStorage.getItem(this.KEY) ?? '[]');
        } catch {
            return [];
        }
        if (!Array.isArray(stored)) return [];
        return stored
            .filter((item): item is Record<string, unknown> => item !== null && typeof item === 'object')
            .map(item => ({
                id: item['id'] as number,
                title: item['title'] as string,
                poster_path: (item['poster_path'] ?? null) as string | null,
                release_date: item['release_date'] as string | undefined,
                seen: (item['seen'] ?? item['watched']) === true,
            }));
    }
}
