import { TmdbMovie, WatchItem } from './movie';

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
    private readonly KEY = 'watchlist';

    private _items = signal<WatchItem[]>(this.loadItems());

    items = this._items.asReadonly();
    count = computed(() => this._items().length);
    watchedCount = computed(() => this._items().filter(m => m.seen).length)

    constructor() {
        // Writing the normalized state back on construction migrates items
        // persisted by older versions (seen-state stored under `watched`)
        // to the `seen` key.
        this.persist();
    }

    add(movie: TmdbMovie) {
        this._items.update(items =>
            items.some(m => m.id === movie.id) ? items : [...items, { id: movie.id, title: movie.title, poster_path: movie.poster_path, release_date: movie.release_date, seen: false }]
        );
        this.persist();
    }

    remove(id: number) {
        this._items.update(items => items.filter(m => m.id !== id));
        this.persist();
    }

    toggleWatched(id: number) {
        this._items.update(items =>
            items.map(m => m.id === id ? { ...m, seen: !m.seen } : m)
        );
        this.persist();
    }

    private persist() {
        localStorage.setItem(this.KEY, JSON.stringify(this._items()));
    }

    private loadItems(): WatchItem[] {
        let stored: unknown = null;
        try {
            stored = JSON.parse(localStorage.getItem(this.KEY) ?? '[]');
        } catch {
            return [];
        }
        if (!Array.isArray(stored)) {
            return [];
        }
        return stored
            .filter((entry): entry is Record<string, unknown> => typeof entry === 'object' && entry !== null)
            .map(entry => ({
                id: entry['id'] as number,
                title: entry['title'] as string,
                poster_path: entry['poster_path'] as string | null | undefined,
                release_date: entry['release_date'] as string | undefined,
                // Items saved before the `watched` -> `seen` rename carry
                // their seen-state under the legacy `watched` key.
                seen: (entry['seen'] ?? entry['watched']) === true,
            }));
    }
}
