```ts
import { computed, Injectable, signal } from '@angular/core';
import { TmdbMovie, WatchItem } from './movie';

interface StoredItem extends Record<string, unknown> {
    seen?: unknown;
    watched?: unknown;
}

@Injectable({ providedIn: 'root' })
export class WatchlistStore {
    private readonly KEY = 'watchlist';

    private _items = signal<WatchItem[]>([]);

    items = this._items.asReadonly();
    count = computed(() => this._items().length);
    watchedCount = computed(() => this._items().filter(m => m.seen).length);

    constructor() {
        const { items, migrated } = this.load();
        this._items.set(items);
        if (migrated) {
            // Rewrite legacy payloads so storage no longer carries the `watched` key.
            this.persist(items);
        }
    }

    add(movie: TmdbMovie) {
        this._items.update(items =>
            items.some(m => m.id === movie.id)
                ? items
                : [...items, { id: movie.id, title: movie.title, poster_path: movie.poster_path, release_date: movie.release_date, seen: false }]
        );
        this.persist(this._items());
    }

    remove(id: number) {
        this._items.update(items => items.filter(m => m.id !== id));
        this.persist(this._items());
    }

    toggleWatched(id: number) {
        this._items.update(items =>
            items.map(m => m.id === id ? { ...m, seen: !m.seen } : m)
        );
        this.persist(this._items());
    }

    private persist(items: WatchItem[]) {
        try {
            localStorage.setItem(this.KEY, JSON.stringify(items));
        } catch {
            // Storage unavailable; the in-memory state remains the source of truth.
        }
    }

    private load(): { items: WatchItem[]; migrated: boolean } {
        const raw = localStorage.getItem(this.KEY);
        if (raw === null) return { items: [], migrated: false };
        let parsed: unknown;
        try {
            parsed = JSON.parse(raw);
        } catch {
            return { items: [], migrated: false };
        }
        if (!Array.isArray(parsed)) return { items: [], migrated: false };

        let migrated = false;
        const items: WatchItem[] = [];
        for (const entry of parsed) {
            if (entry === null || typeof entry !== 'object') continue;
            const record = entry as StoredItem;
            const legacy = !('seen' in record) || 'watched' in record;
            migrated = migrated || legacy;

            let seen = false;
            if (typeof record.seen === 'boolean') {
                seen = record.seen;
            } else if (typeof record.watched === 'boolean') {
                seen = record.watched; // field was renamed from `watched` to `seen`
            }

            const item: WatchItem = {
                id: typeof record.id === 'number' ? record.id : 0,
                title: typeof record.title === 'string' ? record.title : '',
                seen,
            };
            if (record.poster_path === null || typeof record.poster_path === 'string') {
                item.poster_path = record.poster_path as string | null;
            }
            if (typeof record.release_date === 'string') {
                item.release_date = record.release_date;
            }
            items.push(item);
        }
        return { items, migrated };
    }
}
```

